-- IF NOT EXISTS: si la tabla ya existe, no hace nada.
-- Así se puede ejecutar en cada arranque sin errores.
CREATE TABLE IF NOT EXISTS libros (
    -- BIGINT: número entero grande, equivale a Long en Java.
    -- GENERATED BY DEFAULT AS IDENTITY: PostgreSQL asigna el id automáticamente (1, 2, 3...)
    id      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    titulo  VARCHAR(200) NOT NULL UNIQUE,  -- UNIQUE: la base de datos impide títulos repetidos
    autor   VARCHAR(100) NOT NULL,
    paginas INTEGER      NOT NULL CHECK (paginas > 0)  -- CHECK: regla validada por PostgreSQL
);

CREATE TABLE IF NOT EXISTS prestamos (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- REFERENCES libros(id): clave foránea. PostgreSQL impide que un préstamo
    -- apunte a un libro que no existe
    libro_id         BIGINT       NOT NULL REFERENCES libros(id),
    socio            VARCHAR(100) NOT NULL,
    fecha_prestamo   DATE         NOT NULL,
    fecha_devolucion DATE                    -- NULL significa "todavía no devuelto"
);

CREATE TABLE IF NOT EXISTS auditoria (
    id      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    accion  VARCHAR(50)  NOT NULL,
    detalle VARCHAR(500) NOT NULL,
    fecha   TIMESTAMP    NOT NULL   -- fecha y hora
);

-- Índice único PARCIAL: solo afecta a las filas que cumplen el WHERE.
-- Garantiza en la base de datos que un libro tenga como máximo UN préstamo activo.
-- (Lo explico en la sección de aislamiento, más abajo.)
CREATE UNIQUE INDEX IF NOT EXISTS ux_prestamo_activo_por_libro
    ON prestamos (libro_id)
    WHERE fecha_devolucion IS NULL;